UPDATE MEMBERSHIP SET 
MEMBERSHIP_END_DATE = 
	NVL(MEMBERSHIP_END_DATE, SYSDATE) + 
        CASE 
            WHEN #{durationUnit} = 'MONTH' THEN 30 * #{membershipDateValue}
            WHEN #{durationUnit} = 'DAY' THEN #{membershipDateValue}
        END,
MEMBERSHIP_DEL_FL = 'N',
EMPLOYER_NO = #{employerNo},
MEMBERSHIP_BUY_DATE = SYSDATE
WHERE MEMBERSHIP_NO = #{membershipNo}
AND MEMBERSHIP_TYPE = #{membershipType}
